206	    /**
207	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
208	     * owner's {@code registrationDate} (falling back to the current date when no registration date
209	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
210	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
211	     */
212	    @Transient
213	    public String getAgeBand() {
214	        if (this.birthDate == null) {
215	            return null;
216	        }
217	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
218	        int age = Period.between(this.birthDate, reference).getYears();
219	        if (age < 18) {
220	            return "MINOR";
221	        }
222	        if (age < 65) {
223	            return "ADULT";
224	        }
225	        return "SENIOR";
