260	    /**
261	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
262	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
263	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
264	     * the owner's tenure is at least one elapsed fiscal year (measured from the
265	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
266	     */
267	    @Transient
268	    public Integer getMembershipPoints() {
269	        int points = 0;
270	        if (this.email != null && !this.email.isBlank()) {
271	            points += 2;
272	        }
273	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
274	            points += 1;
275	        }
276	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
277	            points += 2;
278	        }
279	        if (hasTenureOverOneFiscalYear()) {
280	            points += 3;
281	        }
282	        return points;
283	    }
284	
285	    /**
286	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
287	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
288	     * points, and level 4 for 6 or more points.
289	     */
290	    @Transient
291	    public Integer getMembershipLevel() {
292	        int points = getMembershipPoints();
293	        if (points <= 1) {
294	            return 1;
295	        }
296	        if (points <= 3) {
297	            return 2;
298	        }
299	        if (points <= 5) {
300	            return 3;
301	        }
302	        return 4;
303	    }
304	
305	    /**
306	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
307	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
308	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
309	     * never qualifies.
310	     */
311	    @Transient
312	    private boolean hasTenureOverOneFiscalYear() {
313	        if (this.registrationDate == null) {
314	            return false;
315	        }
316	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
317	    }
318	
319	    /**
320	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the last two
321	     * digits of the fiscal year of the owner's business-day-adjusted {@code registrationDate}. The
322	     * fiscal year starts on 1 July, so a registration on or after 1 July belongs to the fiscal year
323	     * ending the following 30 June. Returns {@code null} when no {@code registrationDate} has been
324	     * assigned yet, so the field is omitted from the response.
325	     */
326	    @Transient
327	    public String getFiscalYear() {
328	        if (this.registrationDate == null) {
329	            return null;
330	        }
331	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
332	    }
333	
334	    /**
335	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
336	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
337	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
338	     * current year's fiscal year.
339	     */
340	    public static int fiscalYearOf(LocalDate date) {
341	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
342	    }
343	
344	    /**
345	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
346	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
347	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
348	     * has been assigned yet.
349	     */
350	    @Transient
351	    public Integer getCheckDigit() {
352	        if (this.customerCode == null) {
353	            return null;
354	        }
355	        int sum = 0;
356	        boolean dbl = true;
357	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
358	            char c = this.customerCode.charAt(i);
359	            if (c < '0' || c > '9') {
360	                continue;
361	            }
362	            int d = c - '0';
363	            if (dbl) {
364	                d *= 2;
365	                if (d > 9) {
366	                    d -= 9;
367	                }
368	            }
369	            sum += d;
370	            dbl = !dbl;
371	        }
372	        return (10 - (sum % 10)) % 10;
373	    }
374	
375	    /**
376	     * Derive the owner's {@code identityKey}, the single value used to detect duplicate owners:
377	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone and
378	     * email are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or
379	     * blank email contributes an empty segment and an absent {@code householdId} an empty segment.
380	     * Two owners are duplicates only when their whole {@code identityKey} is equal.
381	     */
382	    @Transient
383	    public String getIdentityKey() {
384	        String telephonePart = this.telephone == null ? "" : this.telephone;
385	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
386	        String householdPart = this.householdId == null ? "" : this.householdId;
387	        return telephonePart + "|" + emailPart + "|" + householdPart;
388	    }
389	
390	    public boolean isBulkSignupWarning() {
391	        return this.bulkSignupWarning;
392	    }
393	
394	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
395	        this.bulkSignupWarning = bulkSignupWarning;
396	    }
397	
398	    public Integer getHouseholdMemberCount() {
399	        return this.householdMemberCount;
400	    }
401	
402	    public void setHouseholdMemberCount(Integer householdMemberCount) {
403	        this.householdMemberCount = householdMemberCount;
404	    }
405	
406	    /**
407	     * Whether this owner was flagged at creation as a possible (soft) duplicate: it is not a hard
408	     * {@code identityKey} duplicate, but shares an existing owner's last name and postcode while
409	     * carrying a different telephone. The owner is still created; this flag is advisory.
410	     */
411	    public boolean isPossibleDuplicate() {
412	        return this.possibleDuplicate;
413	    }
414	
415	    public void setPossibleDuplicate(boolean possibleDuplicate) {
416	        this.possibleDuplicate = possibleDuplicate;
417	    }
418	
419	    /**
420	     * The id of the existing owner this one soft-matched against (same last name and postcode,
421	     * different telephone), or {@code null} when {@link #isPossibleDuplicate()} is {@code false}.
422	     */
423	    public Integer getPossibleDuplicateOf() {
424	        return this.possibleDuplicateOf;
425	    }
426	
427	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
428	        this.possibleDuplicateOf = possibleDuplicateOf;
429	    }
430	
431	    /**
432	     * Whether this owner has been soft-deleted: DELETE /api/owners/{id} sets this flag rather than
433	     * removing the row, so the owner is retained and still readable but is ignored by the create
434	     * endpoint's duplicate and identity checks. A newly created owner is not deleted.
435	     */
436	    public boolean isDeleted() {
437	        return this.deleted;
438	    }
439	
440	    public void setDeleted(boolean deleted) {
441	        this.deleted = deleted;
442	    }
443	
444	    public boolean isSharesHousehold() {
445	        return this.sharesHousehold;
446	    }
447	
448	    public void setSharesHousehold(boolean sharesHousehold) {
449	        this.sharesHousehold = sharesHousehold;
450	    }
451	
452	    protected Set<Pet> getPetsInternal() {
453	        if (this.pets == null) {
454	            this.pets = new HashSet<>();
455	        }
456	        return this.pets;
457	    }
458	
459	    protected void setPetsInternal(Set<Pet> pets) {
460	        this.pets = pets;
461	    }
462	
463	    public List<Pet> getPets() {
464	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
465	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
466	        return Collections.unmodifiableList(sortedPets);
467	    }
468	
469	    public void setPets(List<Pet> pets) {
470	        this.pets = new HashSet<>(pets);
471	    }
472	
473	    public void addPet(Pet pet) {
474	        getPetsInternal().add(pet);
475	        pet.setOwner(this);
476	    }
477	
478	    /**
479	     * Return the Pet with the given name, or null if none found for this Owner.
480	     *
481	     * @param name to test
482	     * @return true if pet name is already in use
483	     */
484	    public Pet getPet(String name) {
485	        return getPet(name, false);
486	    }
487	
488	    /**
489	     * Return the Pet with the given name, or null if none found for this Owner.
490	     *
491	     * @param name to test
492	     * @return true if pet name is already in use
493	     */
494	    public Pet getPet(String name, boolean ignoreNew) {
495	        name = name.toLowerCase();
496	        for (Pet pet : getPetsInternal()) {
497	            if (!ignoreNew || !pet.isNew()) {
498	                String compName = pet.getName();
499	                compName = compName.toLowerCase();
500	                if (compName.equals(name)) {
501	                    return pet;
502	                }
503	            }
504	        }
505	        return null;
506	    }
507	
508	    public Pet getPet(Integer petId) {
509	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
510	    }
511	
512	    @Override
513	    public String toString() {
514	        return new ToStringCreator(this)
515	
516	            .append("id", this.getId())
517	            .append("new", this.isNew())
518	            .append("lastName", this.getLastName())
519	            .append("firstName", this.getFirstName())
520	            .append("address", this.address)
521	            .append("city", this.city)
522	            .append("telephone", this.telephone)
523	            .toString();
524	    }
525	}
